import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { lessonsAPI } from '../../services/api';
import { Icon, IconSizes, IconColors } from '../../components/common/IconTheme';
import ConfirmModal from '../../components/common/ConfirmModal';
import './CreateCourse.css';

const CreateLesson = () => {
  const { user, addNotification } = useAuth();
  const navigate = useNavigate();
  const { moduleId, lessonId } = useParams();
  const isEditing = !!lessonId;

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    type: '',
    content: '',
    duration: '',
    order: 1,
    isPublished: false,
    remarks: ''
  });
  const [file, setFile] = useState(null);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [module, setModule] = useState(null);
  const [course, setCourse] = useState(null);
  const [existingOrders, setExistingOrders] = useState([]);
  const [showDiscardModal, setShowDiscardModal] = useState(false);
  const [objectUrl, setObjectUrl] = useState('');

  useEffect(() => {
    // Vérifier que l'utilisateur est un tuteur
    if (!user) {
      navigate('/login');
      return;
    }

    if (user.role !== 'tuteur') {
      navigate('/dashboard');
      return;
    }

    // Charger les informations du module et des leçons existantes
    loadModuleAndLessons();
  }, [user, navigate, moduleId, lessonId]);

  const loadModuleAndLessons = async () => {
    try {
      setLoading(true);

      // Charger le module
        const moduleResponse = await fetch(`http://localhost:5000/api/modules/${moduleId}`);
        if (moduleResponse.ok) {
          const moduleData = await moduleResponse.json();
          if (moduleData.success) {
            setModule(moduleData.data);

          // Charger les informations du cours
            const courseResponse = await fetch(`http://localhost:5000/api/courses/${moduleData.data.course}`);
            if (courseResponse.ok) {
              const courseData = await courseResponse.json();
              if (courseData.success) {
                setCourse(courseData.data);
              }
            }

          // Charger les leçons existantes pour l'ordre
            const lessonsResponse = await lessonsAPI.getByModule(moduleId);
            if (lessonsResponse.data.success) {
            const existingLessons = lessonsResponse.data.data || [];
            const orders = existingLessons
              .filter(l => !isEditing || l._id !== lessonId)
              .map(l => l?.order)
              .filter(o => typeof o === 'number' && Number.isFinite(o));
            setExistingOrders(orders);
            const maxOrder = orders.length > 0 ? Math.max(...orders) : 0;
            setFormData(prev => ({ ...prev, order: maxOrder + 1 }));
          }

          // Si on édite, charger la leçon
          if (isEditing) {
            const lessonResponse = await lessonsAPI.getById(lessonId);
            if (lessonResponse.data.success) {
              const lessonData = lessonResponse.data.data;
              setFormData({
                title: lessonData.title || '',
                description: lessonData.description || '',
                type: lessonData.type || 'document',
                content: lessonData.content || '',
                estimatedDuration: lessonData.estimatedDuration || '',
                order: lessonData.order || 1,
                isPublished: lessonData.isPublished || false,
                remarks: lessonData.remarks || ''
              });
            }
            }
          }
        }
      } catch (error) {
        console.error('Erreur chargement données:', error);
        setError('Erreur lors du chargement des données');
      } finally {
        setLoading(false);
      }
    };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    // If changing type, reset file and content to avoid stale previews
    if (name === 'type') {
      setFile(null);
      setFormData(prev => ({
        ...prev,
        type: value,
        content: ''
      }));
    } else {
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation
    if (!formData.type) {
      setError('Veuillez sélectionner le type de contenu');
      return;
    }
    if (!formData.title.trim()) {
      setError('Le titre est requis');
      return;
    }
    if (!formData.duration || !Number.isFinite(parseInt(formData.duration))) {
      setError('La durée (en minutes) est requise');
      return;
    }

    // Content validation: require either file (for document/video) or URL/content
    if ((formData.type === 'document' || formData.type === 'video')) {
      if (!file && !formData.content.trim()) {
        setError('Veuillez fournir un fichier ou une URL pour le contenu');
        return;
      }
    } else if (!formData.content.trim()) {
      setError('Le contenu est requis');
      return;
    }

    // Vérifier les conflits d'ordre
    if (existingOrders.includes(parseInt(formData.order)) && 
        (!isEditing || parseInt(formData.order) !== formData.order)) {
      // Réorganiser automatiquement
      await reorderLessons();
    }

    await saveLesson();
  };

  // Cleanup object URL when file changes or component unmounts
  useEffect(() => {
    if (file) {
      const url = URL.createObjectURL(file);
      setObjectUrl(url);
      return () => {
        URL.revokeObjectURL(url);
        setObjectUrl('');
      };
    } else {
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
        setObjectUrl('');
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [file]);

  const reorderLessons = async () => {
    try {
      const conflictingOrder = parseInt(formData.order);
      const lessonsResponse = await lessonsAPI.getByModule(moduleId);
      if (lessonsResponse.data.success) {
        const allLessons = lessonsResponse.data.data || [];

        // Créer un nouvel ordre pour tous les modules
        let newOrder = 1;
        const reorderedLessons = [];

        // Traiter d'abord les leçons avec un ordre < à l'ordre souhaité
        allLessons
          .filter(l => (!isEditing || l._id !== lessonId) && l.order < conflictingOrder)
          .sort((a, b) => a.order - b.order)
          .forEach(l => {
            reorderedLessons.push({ ...l, order: newOrder++ });
          });

        // Traiter les leçons avec un ordre >= à l'ordre souhaité
        allLessons
          .filter(l => (!isEditing || l._id !== lessonId) && l.order >= conflictingOrder)
          .sort((a, b) => a.order - b.order)
          .forEach(l => {
            reorderedLessons.push({ ...l, order: newOrder++ });
          });

        // Mettre à jour l'ordre de toutes les leçons
        for (const lesson of reorderedLessons) {
          try {
            await lessonsAPI.update(lesson._id, { order: lesson.order });
          } catch (error) {
            console.error(`Erreur réorganisation leçon ${lesson._id}:`, error);
          }
        }
      }
    } catch (error) {
      console.error('Erreur réorganisation leçons:', error);
    }
  };

  const saveLesson = async () => {
    try {
      setSaving(true);
      setError('');

      // Always send as FormData so multer parses fields (backend requires it)
      const computedOrder = Number.isFinite(parseInt(formData.order))
        ? parseInt(formData.order)
        : ((existingOrders.length > 0 ? Math.max(...existingOrders) : 0) + 1);
      const computedDuration = parseInt(formData.duration);
      const lessonData = new FormData();
      lessonData.append('title', formData.title.trim());
      lessonData.append('description', formData.description.trim());
      lessonData.append('type', formData.type);
      lessonData.append('duration', String(computedDuration));
      lessonData.append('order', String(computedOrder));
      lessonData.append('isPublished', String(!!formData.isPublished));
      lessonData.append('remarks', formData.remarks.trim());
      lessonData.append('module', moduleId);
      if (formData.content?.trim()) lessonData.append('content', formData.content.trim());
      if (file) lessonData.append('file', file);

      let response;
      if (isEditing) {
        response = await lessonsAPI.update(lessonId, lessonData);
      } else {
        response = await lessonsAPI.create(lessonData);
      }

      if (response.data.success) {
        const message = isEditing ? 'Leçon modifiée avec succès !' : 'Leçon créée avec succès !';
        setSuccess(message);
        addNotification(message, 'success');
        setTimeout(() => navigate(`/tutor/manage-lessons/${moduleId}`), 1200);
      } else {
        setError(response.data.message || `Erreur lors de la ${isEditing ? 'modification' : 'création'} de la leçon`);
      }
    } catch (error) {
      if (error.response?.data?.message) {
        setError(error.response.data.message);
      } else {
        setError(`Erreur lors de la ${isEditing ? 'modification' : 'création'} de la leçon`);
      }
    } finally {
      setSaving(false);
    }
  };

  const handleDiscardChanges = () => {
    setShowDiscardModal(true);
  };

  const getContentPlaceholder = () => {
    switch (formData.type) {
      case 'document':
        return 'URL du document (PDF, Word, etc.) ou contenu textuel...';
      case 'url':
        return 'URL de la ressource web...';
      case 'video':
        return 'URL du fichier vidéo...';
      case 'youtube':
        return 'URL YouTube (ex: https://youtube.com/watch?v=...)';
      case 'quiz':
        return 'Description du quiz ou questions...';
      default:
        return 'Contenu de la leçon...';
    }
  };

  if (loading) {
    return (
      <div className="create-course-page">
        <div className="create-course-container">
          <div style={{ textAlign: 'center', padding: '4rem 2rem' }}>
            <Icon name="loader" size={IconSizes.xl} color={IconColors.gray} className="spin" />
            <p>Chargement...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="create-course-page">
      <div className="create-course-container">

        {/* Page header */}
        <div className="page-header">
          <div className="header-content">
          <h1>
              <Icon name={isEditing ? 'edit' : 'plus'} size={IconSizes.lg} color={IconColors.primary} />
              {isEditing ? 'Modifier la leçon' : 'Créer une nouvelle leçon'}
          </h1>
            <p>
              {course?.title ? `Cours : ${course.title}` : 'Chargement du cours...'} 
              {module?.title && ` - Module : ${module.title}`}
            </p>
          </div>
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button
              onClick={handleDiscardChanges}
              className="btn btn-outline"
            >
              <Icon name="arrowLeft" size={IconSizes.sm} color={IconColors.gray} />
              Annuler
            </button>
            <button
              onClick={handleSubmit}
              disabled={saving}
              className="create-course-btn"
            >
              {saving ? (
                <>
                  <Icon name="loader" size={IconSizes.sm} color={IconColors.white} className="spin" />
                  Enregistrement...
                </>
              ) : (
                <>
                  <Icon name="save" size={IconSizes.sm} color={IconColors.white} />
                  {isEditing ? 'Modifier' : 'Créer'}
                </>
              )}
            </button>
          </div>
        </div>

        {error && (
          <div className="alert alert-error">
            <Icon name="error" size={IconSizes.sm} color={IconColors.danger} />
            {error}
          </div>
        )}

        {success && (
          <div className="alert alert-success">
            <Icon name="check" size={IconSizes.sm} color={IconColors.primary} />
            {success}
          </div>
        )}

        {/* Lesson Form */}
        <div className="course-form-container">
          <form onSubmit={handleSubmit} className="course-form">

            {/* Lesson Title */}
            <div className="form-group">
              <label htmlFor="title" className="form-label">
                <Icon name="hash" size={IconSizes.sm} color={IconColors.primary} />
                Titre de la leçon *
              </label>
              <input
                type="text"
                id="title"
                name="title"
                value={formData.title}
                onChange={handleChange}
                className="form-input"
                placeholder="Ex: Introduction aux variables en JavaScript"
                required
                maxLength={100}
              />
              <small className="form-help">
                {formData.title.length}/100 caractères
              </small>
            </div>

            {/* Lesson Description */}
            <div className="form-group">
              <label htmlFor="description" className="form-label">
                <Icon name="fileText" size={IconSizes.sm} color={IconColors.primary} />
                Description de la leçon
              </label>
              <textarea
                id="description"
                name="description"
                value={formData.description}
                onChange={handleChange}
                className="form-textarea"
                placeholder="Décrivez le contenu et les objectifs de cette leçon..."
                rows={3}
                maxLength={300}
              />
              <small className="form-help">
                {formData.description.length}/300 caractères
              </small>
            </div>

            {/* Lesson Type */}
            <div className="form-group">
              <label htmlFor="type" className="form-label">
                <Icon name="layers" size={IconSizes.sm} color={IconColors.primary} />
                Type de contenu *
              </label>
              <select
                id="type"
                name="type"
                value={formData.type}
                onChange={handleChange}
                className="form-input"
                required
              >
                <option value="" disabled>Sélectionner le type</option>
                <option value="document">Document (PDF, Word, etc.)</option>
                <option value="url">Lien web</option>
                <option value="video">Vidéo</option>
                <option value="youtube">Vidéo YouTube</option>
                <option value="quiz">Quiz</option>
              </select>
              <small className="form-help">
                Le type détermine comment le contenu sera affiché
              </small>
            </div>

            {/* Lesson Content - shows only after type selection */}
            {formData.type && (
              <div className="form-group">
              <label htmlFor="content" className="form-label">
                <Icon name="file" size={IconSizes.sm} color={IconColors.primary} />
                Contenu de la leçon *
              </label>
              {(formData.type === 'document' || formData.type === 'video') ? (
                <>
                  <input
                    type="file"
                    accept={formData.type === 'document' ? '.pdf,.doc,.docx,.ppt,.pptx,.txt' : 'video/*'}
                    onChange={(e) => setFile(e.target.files && e.target.files[0] ? e.target.files[0] : null)}
                    className="form-input"
                  />
                  <small className="form-help">Vous pouvez aussi fournir une URL ci-dessous</small>
                <input
                  type="url"
                    id="content"
                    name="content"
                    value={formData.content}
                    onChange={handleChange}
                    className="form-input"
                    placeholder={getContentPlaceholder()}
                  />
                </>
              ) : (
                <textarea
                  id="content"
                  name="content"
                  value={formData.content}
                  onChange={handleChange}
                  className="form-textarea"
                  placeholder={getContentPlaceholder()}
                  required
                  rows={4}
                  maxLength={1000}
                />
              )}
              {!(formData.type === 'document' || formData.type === 'video') && (
                <small className="form-help">
                  {formData.content.length}/1000 caractères
                </small>
              )}
              {/* Preview */}
              <div className="lesson-preview">
                {formData.type === 'youtube' && formData.content && (
                  (() => {
                    const match = formData.content.match(/(?:v=|youtu\.be\/)([A-Za-z0-9_-]{11})/);
                    const vid = match ? match[1] : '';
                    return vid ? (
                      <div className="preview-frame">
                        <iframe
                          src={`https://www.youtube.com/embed/${vid}`}
                          title="YouTube video"
                          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                          allowFullScreen
                        />
                      </div>
                    ) : null;
                  })()
                )}
                {formData.type === 'video' && (objectUrl || formData.content) && (
                  <div className="preview-frame">
                    <video src={objectUrl || formData.content} controls />
                  </div>
                )}
                {formData.type === 'document' && (
                  <div className="doc-preview">
                    {file ? (
                      <div className="doc-chip">
                        <Icon name="fileText" size={IconSizes.xs} color={IconColors.primary} />
                        <span>{file.name}</span>
                      </div>
                    ) : (
                      formData.content && (formData.content.endsWith('.pdf') ? (
                        <div className="preview-frame">
                          <iframe src={formData.content} title="Document PDF" />
                        </div>
                      ) : (
                        <a href={formData.content} className="doc-link" target="_blank" rel="noreferrer">
                          Ouvrir le document
                        </a>
                      ))
                    )}
                  </div>
                )}
                {formData.type === 'url' && formData.content && (
                  <a href={formData.content} className="doc-link" target="_blank" rel="noreferrer">
                    Ouvrir le lien
                  </a>
                )}
              </div>
              </div>
            )}

            {/* Estimated Duration */}
            <div className="form-group">
              <label htmlFor="estimatedDuration" className="form-label">
                <Icon name="clock" size={IconSizes.sm} color={IconColors.primary} />
                Durée (minutes)
              </label>
              <input
                type="number"
                id="duration"
                name="duration"
                value={formData.duration}
                onChange={handleChange}
                className="form-input"
                min="1"
                max="480"
                placeholder="Ex: 15"
              />
              <small className="form-help">
                Temps pour compléter cette leçon (1-480 minutes)
              </small>
            </div>

            {/* Lesson Order */}
              <div className="form-group">
              <label htmlFor="order" className="form-label">
                <Icon name="list" size={IconSizes.sm} color={IconColors.primary} />
                Ordre de la leçon *
              </label>
                  <input
                type="number"
                id="order"
                name="order"
                value={formData.order}
                onChange={handleChange}
                className="form-input"
                min="1"
                required
              />
              <small className="form-help">
                L'ordre détermine la séquence d'affichage des leçons dans le module
              </small>
            </div>

            {/* Remarks */}
            <div className="form-group">
              <label htmlFor="remarks" className="form-label">
                <Icon name="messageSquare" size={IconSizes.sm} color={IconColors.primary} />
                Remarques
              </label>
              <textarea
                id="remarks"
                name="remarks"
                value={formData.remarks}
                onChange={handleChange}
                className="form-textarea"
                placeholder="Notes additionnelles, instructions spéciales, etc."
                rows="2"
                maxLength={200}
              />
              <small className="form-help">
                {formData.remarks.length}/200 caractères
              </small>
          </div>


          </form>
          </div>
      </div>

      {/* Discard Changes Modal */}
      <ConfirmModal
        open={showDiscardModal}
        title="Modifications non sauvegardées"
        message="Vous avez des modifications non sauvegardées. Voulez-vous vraiment quitter sans sauvegarder ?"
        confirmLabel="Quitter sans sauvegarder"
        cancelLabel="Continuer l'édition"
        variant="warning"
        onConfirm={() => navigate(`/tutor/manage-lessons/${moduleId}`)}
        onCancel={() => setShowDiscardModal(false)}
      />
    </div>
  );
};

export default CreateLesson;
